const onIn=ev=>{const el=ev.target;if(!el.dataset||!el.dataset.in||!IN[el.dataset.in])return;const chg=el.matches(CHG);if(ev.type==='input'&&chg)return;if(ev.type==='change'&&!chg)return;IN[el.dataset.in](el)};
