{let c='';THEMES.slice(-11).forEach(t=>{if(t[0]==='custom')return;c+=`[data-theme=${t[0]}]{--bg:${t[4]};--a1:${t[2]};--a2:${t[3]}${t[5]?';--card:rgba(255,255,255,.8);--card2:#fff;--line:rgba(30,20,40,.1);--tx:#1c1722;--mut:#6c6577;--ok:#12a066;--bad:#d6334f':''}}\n`});const st=document.createElement('style');st.textContent=c;document.head.appendChild(st)}
