function domColor(c){try{const w=c.width,h=c.height,d=c.getContext('2d').getImageData(0,0,w,h).data,B={};let ar=0,ag=0,ab=0,an=0;for(let i=0;i<d.length;i+=16){const a=d[i+3];if(a<140)continue;const r=d[i],g=d[i+1],b=d[i+2];ar+=r;ag+=g;ab+=b;an++;const mx=Math.max(r,g,b),mn=Math.min(r,g,b),sat=mx?(mx-mn)/mx:0,v=mx/255;if(sat<.28||v<.28)continue;const k=(r>>5)+','+(g>>5)+','+(b>>5),o=B[k]||(B[k]={n:0,r:0,g:0,b:0,w:0});o.n++;o.r+=r;o.g+=g;o.b+=b;o.w+=.3+sat*v}let best=null;for(const k in B)if(!best||B[k].w>best.w)best=B[k];const hx=n=>Math.round(n).toString(16).padStart(2,'0');if(best)return'#'+hx(best.r/best.n)+hx(best.g/best.n)+hx(best.b/best.n);if(an)return'#'+hx(ar/an)+hx(ag/an)+hx(ab/an)}catch(e){}return''}
