function revealIO(anim){if(!anim||S.set.calm||!('IntersectionObserver' in window))return;const els=$$('#page .rise').filter(e=>e.getBoundingClientRect().top>innerHeight*.92);if(!els.length)return;els.forEach(e=>e.style.animationPlayState='paused');const io=new IntersectionObserver(es=>es.forEach(x=>{if(x.isIntersecting){x.target.style.animationDelay='0s';x.target.style.animationPlayState='running';io.unobserve(x.target)}}),{rootMargin:'0px 0px -6% 0px',threshold:.04});els.forEach(e=>io.observe(e));setTimeout(()=>{els.forEach(e=>e.style.animationPlayState='running');io.disconnect()},6000)}
