let GD7=null;
addEventListener('pointermove',e=>{if(!GD7||!GD7.sc.isConnected)return;const d=e.clientX-GD7.x;if(Math.abs(d)>4){GD7.m=1;GD7.sc.classList.add('drag')}if(GD7.m)GD7.sc.scrollLeft=GD7.l-d});
addEventListener('pointerup',()=>{if(GD7&&GD7.m){const s=GD7.sc;setTimeout(()=>s.classList.remove('drag'),0)}GD7=null});
function gtRestore(){
 const sc=$('#gtsc');if(!sc)return;
 const go=()=>{
  if(UI.gsl==null){const n=$('.gt-now',sc);if(n){const x=n.offsetLeft+($('.gt-over .gt-trk',sc)||{offsetLeft:0}).offsetLeft;sc.scrollLeft=Math.max(0,x-sc.clientWidth*.4)}}
  else sc.scrollLeft=UI.gsl};
 go();requestAnimationFrame(go);
 sc.addEventListener('scroll',()=>{UI.gsl=sc.scrollLeft},{passive:true});
 sc.addEventListener('pointerdown',e=>{if(e.pointerType!=='mouse'||e.button!==0)return;GD7={sc,x:e.clientX,l:sc.scrollLeft,m:0}});
 sc.addEventListener('click',e=>{if(sc.classList.contains('drag')){e.stopPropagation();e.preventDefault()}},true);
}
{const _r7=render;render=function(a){_r7(a);try{fold7();if(UI.page==='roadmap')gtRestore()}catch(e){console.error(e)}}}
