/* ===== arrow-key music control: ▲▼ volume, ◀▶ prev/next (only while music is playing) ===== */
document.addEventListener('keydown',e=>{
 const k=e.key;if(!['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(k)||e.ctrlKey||e.metaKey||e.altKey)return;
 const t=e.target,tg=(t&&t.tagName)||'';if(tg==='TEXTAREA'||tg==='SELECT'||t&&t.isContentEditable||tg==='INPUT'&&t.type!=='range'&&t.type!=='checkbox')return;
 if(typeof FV!=='undefined'&&FV)return;
 if(AU.paused)return;
 e.preventDefault();
 if(k==='ArrowUp'||k==='ArrowDown'){
  MZ.vol=Math.max(0,Math.min(1,Math.round((MZ.vol+(k==='ArrowUp'?.05:-.05))*100)/100));
  mzApplyVol();mzSave();
  document.querySelectorAll('[data-in="mzVol"]').forEach(x=>x.value=Math.round(MZ.vol*100));
  toast('🔊 Volume '+Math.round(MZ.vol*100)+'%','ok');
 }else if(!e.repeat){
  k==='ArrowRight'?ACT.mzNext():ACT.mzPrev();
 }
},true);

/* rotating motivation line (header + phone strip) */
setInterval(()=>{const qs=[...document.querySelectorAll('.hx-q')];if(!qs.length)return;window.__hq=(window.__hq||0)+1;qs.forEach(q=>{let L;try{L=JSON.parse(q.dataset.l)}catch(e){return}if(L.length<2)return;const p=q.querySelector('p');q.classList.add('out');setTimeout(()=>{if(!q.isConnected)return;{const pr=qp(L[window.__hq%L.length]);p.innerHTML=pr[1];const ic=q.querySelector('.hx-qi');if(ic)ic.textContent=pr[0]||q.dataset.di||'🎯'}q.classList.remove('out');q.classList.add('in');setTimeout(()=>q.classList.remove('in'),700)},380)})},12000);

