function cdJourney(id){
 const a=activeIdx(),st=gc(id),days=[],revs=[];
 for(let k=0;k<TOTAL;k++){if(dChs(k).includes(id))days.push(k);if(revCs(k).includes(id))revs.push(k)}
 const sS=k=>isDone(k)?['done','✓ সম্পন্ন']:(k===a&&!allDone())?['now','আজ']:k<a?['miss','বাদ পড়েছে']:['up','আসছে'];
 const sR=k=>{const dd=gd(k);return dd&&dd.rev&&dd.rev[id]?['done','✓ revise']:(k===a&&!allDone())?['now','আজ']:k<a?['miss','বাকি']:['up','আসছে']};
 const row=(k,rv,s)=>`<button class="cj-i ${s[0]} ${rv?'rv':''}" data-act="cdDay" data-i="${k}"><span class="cj-d"><b>${k+1}</b><small>Day</small></span><span class="cj-x"><b>${rv?'🌿 Revision':'📖 পড়ার দিন'}</b><small>${fDW(dayDate(k))}</small></span><em>${s[1]}</em></button>`;
 const cls=clTot(id)||0,tl=[{ic:'🎓',n:'Class',i:0,m:cls,x:'',c:'#38bdf8'}];
 [1,2,3].forEach(i=>{const g=pzAgg(id,i),T=PZT[i];tl.push({ic:T.ic,n:T.n,i,m:g.m,x:g.n?(i===3?Math.round(g.ok/g.n*100)+'% · '+g.n+' MCQ':g.n+' '+T.u):'',c:T.c})});
 const tot=tl.reduce((x,y)=>x+(y.m||0),0),ses=pzGet(id).length;
 const tiles=tl.map(o=>`<div class="cj-k ${st.t[o.i]?'ok':''}" style="--tc:${o.c}"><span class="cj-ti">${o.ic}</span><b>${o.n}</b><em>${o.m?fmM(o.m):'—'}</em><small>${o.x||(st.t[o.i]?'শেষ':'বাকি')}</small></div>`).join('');
 return`<div class="cj"><div class="cj-hd"><b>⏱ মোট সময় দিয়েছ</b><span>${tot?fmM(tot):'—'}${ses?' · '+ses+' session':''}</span></div><div class="cj-g">${tiles}</div><div class="cj-hd"><b>📅 কবে কী পড়া</b><span>${days.length} দিন${revs.length?' · '+revs.length+' revision':''}</span></div><div class="cj-l">${days.map(k=>row(k,0,sS(k))).join('')}${revs.map(k=>row(k,1,sR(k))).join('')}${days.length||revs.length?'':'<div class="mut sm">Plan-e ei chapter nei</div>'}</div></div>`}
{const _cb=cdBody;cdBody=function(){let h=_cb();const d=UI.cd;if(d&&d.t==='c'&&CH[d.k]){const mk='<label class="l" style="margin-top:12px;display:block">Progress</label>';if(h.includes(mk))h=h.replace(mk,cdJourney(d.k)+mk)}return h}}
